-- ============================================================
-- SECTION 1: USERS (Patients, Doctors, Proxies, Admin)
-- ============================================================

-- Temporarily allow NULL so we can populate system_id after insert
ALTER TABLE users ALTER COLUMN system_id DROP NOT NULL;

ON CONFLICT (email) DO NOTHING;

-- Populate system_id for any users inserted above that don't have one yet
UPDATE users SET system_id =
  CASE
    WHEN role = 'PATIENT'   THEN 'PAT-' || LPAD(user_id::text, 5, '0')
    WHEN role = 'DOCTOR'    THEN 'DOC-' || LPAD(user_id::text, 5, '0')
    WHEN role = 'CAREGIVER' THEN 'CGV-' || LPAD(user_id::text, 5, '0')
    WHEN role = 'ADMIN'     THEN 'ADM-' || LPAD(user_id::text, 5, '0')
    ELSE 'USR-' || LPAD(user_id::text, 5, '0')
  END
WHERE system_id IS NULL;

ALTER TABLE users ALTER COLUMN system_id SET NOT NULL;

