INSERT INTO doctors (system_id, specialization, license_no, bio, is_active, created_at) VALUES
((SELECT system_id FROM users WHERE email = 'james.banda@carenexus.com'),       'General Practice',        'ZW-GP-2019-0042',    'Dr. James Banda is a seasoned general practitioner with over 10 years of experience in primary care. He holds an MBChB from the University of Zimbabwe and has a special interest in preventive medicine and chronic disease management.',                                                                                            TRUE, '2025-09-15T09:00:00Z'),
((SELECT system_id FROM users WHERE email = 'amara.osei@carenexus.com'),        'Cardiology',              'GH-CARD-2017-0118',  'Dr. Amara Osei is a consultant cardiologist trained at Korle Bu Teaching Hospital and the University of Ghana. She specialises in interventional cardiology, heart failure management, and echocardiography with over 12 years of clinical practice.',                                                                                  TRUE, '2025-08-10T08:00:00Z'),
((SELECT system_id FROM users WHERE email = 'rudo.sithole@carenexus.com'),      'Pediatrics',              'ZW-PED-2020-0077',   'Dr. Rudo Sithole is a dedicated paediatrician with a passion for child health and development. She completed her fellowship at the University of Cape Town and focuses on neonatal care, childhood vaccinations, and developmental disorders.',                                                                                       TRUE, '2025-07-05T09:00:00Z'),
((SELECT system_id FROM users WHERE email = 'tafara.mutasa@carenexus.com'),     'Dermatology',             'ZW-DERM-2018-0033',  'Dr. Tafara Mutasa is a board-certified dermatologist specialising in skin disorders, cosmetic dermatology, and skin cancer screening. He trained at the University of Pretoria and has extensive experience managing complex dermatological conditions across all skin types.',                                                      TRUE, '2025-06-20T10:00:00Z'),
((SELECT system_id FROM users WHERE email = 'nokuthula.mthembu@carenexus.com'), 'Obstetrics & Gynaecology','ZA-OBGYN-2016-0205', 'Dr. Nokuthula Mthembu is an obstetrician and gynaecologist with 14 years of experience in maternal-foetal medicine and minimally invasive gynaecological surgery. She trained at the University of KwaZulu-Natal and is passionate about women''s reproductive health.',                                                         TRUE, '2025-10-01T08:00:00Z'),
((SELECT system_id FROM users WHERE email = 'emeka.eze@carenexus.com'),         'Internal Medicine',       'NG-IM-2015-0389',    'Dr. Emeka Eze is a specialist in internal medicine with sub-specialty training in endocrinology and diabetes management. He completed his residency at the Lagos University Teaching Hospital and has a strong research background in metabolic disorders.',                                                                      TRUE, '2025-11-15T09:00:00Z'),
((SELECT system_id FROM users WHERE email = 'fatima.alhassan@carenexus.com'),   'Psychiatry',              'KE-PSY-2018-0091',   'Dr. Fatima Al-Hassan is a consultant psychiatrist with expertise in mood disorders, anxiety, and trauma-informed care. She trained at the University of Nairobi and the Maudsley Hospital, London, and advocates strongly for mental health awareness across East Africa.',                                                    TRUE, '2025-12-01T08:00:00Z')
