INSERT INTO consultations (consultation_id, appointment_id, patient_system_id, doctor_system_id, chief_complaint, history_of_present_illness, physical_examination, clinical_notes, diagnosis, treatment_plan, follow_up_instructions, follow_up_required, follow_up_date, duration_minutes, status, started_at, completed_at, created_at) VALUES
(1,  2,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),    (SELECT system_id FROM users WHERE email='amara.osei@carenexus.com'),        'Intermittent chest pain and palpitations for approximately two weeks, worse on exertion.', 'Patient is a 29-year-old female presenting with a two-week history of intermittent chest tightness and palpitations. Episodes last 5–10 minutes, occurring 2–3 times daily, associated with stress and caffeine intake. No syncope, dyspnoea at rest, or diaphoresis. No family history of cardiac disease.', 'General: Well-appearing, no acute distress. Vitals: HR 78 bpm (regular), BP 122/78 mmHg, SpO2 99%. Cardiovascular: Regular rate and rhythm, no murmurs, rubs or gallops. Chest: Clear to auscultation bilaterally.', '12-lead ECG reviewed via video — normal sinus rhythm, no ST changes. Symptoms appear strongly linked to psychosocial stressors and caffeine. Low pre-test probability for structural cardiac pathology.', 'Benign palpitations, likely stress-induced. No structural cardiac disease identified on clinical assessment or ECG review.', '1. Lifestyle modification: reduce caffeine to <1 cup/day, improve sleep hygiene.\n2. Stress management techniques — referred to occupational health support.\n3. If palpitations worsen, proceed to 24-hour Holter monitor and echocardiogram.', 'Return to GP if symptoms worsen or new symptoms develop. Cardiology review in 3 months if symptoms persist.', FALSE, NULL, 45, 'COMPLETED', '2026-07-10T14:00:00', '2026-07-10T14:45:00', '2026-07-10T14:00:00'),
(2,  3,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),    (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),       'Sore throat and persistent cough for 5 days, associated with low-grade fever.', 'Patient presents with a 5-day history of worsening sore throat, dry cough, and malaise. Temperature peaked at 38.1°C at home. No rhinorrhoea or nasal congestion. No known sick contacts. Reports difficulty swallowing solids but able to tolerate fluids.', 'General: Mildly unwell, flushed. Temp 37.9°C, HR 92 bpm, BP 118/74, SpO2 98%. ENT: Oropharynx erythematous with bilateral tonsillar enlargement (+2), right-sided white exudate present. Cervical lymphadenopathy: tender, mobile nodes bilaterally.', 'Centor score 4/4 (tonsillar exudate, tender anterior cervical lymphadenopathy, fever, absence of cough). High clinical suspicion for bacterial pharyngitis (Group A Streptococcus). Treating empirically per local guidelines.', 'Bacterial pharyngitis (Group A Streptococcal — presumptive). Right-sided tonsillar exudate.', '1. Amoxicillin 500mg TDS for 7 days.\n2. Paracetamol 1g QDS PRN for fever and pain.\n3. Warm saline gargles 4x daily.\n4. Encourage adequate fluid intake and rest.', 'Return if symptoms do not improve within 48–72 hours of antibiotics, or if rash develops (exclude scarlet fever). Complete full antibiotic course.', FALSE, NULL, 30, 'COMPLETED', '2026-06-28T11:00:00', '2026-06-28T11:30:00', '2026-06-28T11:00:00'),
(3,  9,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),    (SELECT system_id FROM users WHERE email='fatima.alhassan@carenexus.com'),   'Persistent anxiety, low mood, sleep difficulties, and difficulty coping with workplace stress over the past 6 weeks.', 'Patient is a 29-year-old female with no prior psychiatric history, presenting with a 6-week history of excessive worry, difficulty concentrating, and physical tension. She reports significant occupational stress following a recent promotion. Sleep onset latency of 60–90 minutes, frequent waking. Appetite mildly reduced.', 'Mental State Examination: Well-dressed, cooperative, mild psychomotor tension. Mood: "Anxious and exhausted". Affect: Congruent, reactive. Thought form: Logical. Insight: Good.', 'Generalised Anxiety Disorder (GAD-7 score 14/21, indicating moderate anxiety). Rule out depression. No safety concerns, no suicidal ideation. Good social support. Sleep quality strongly correlated with anxiety level.', 'Generalised Anxiety Disorder (GAD-7 score 14). Reactive anxiety secondary to occupational stress and perfectionist traits. No depressive disorder identified. Sleep disturbance secondary to anxiety.', '1. Cognitive-Behavioural Therapy (CBT) referral for anxiety management and cognitive restructuring.\n2. Sleep hygiene optimisation: consistent bedtime routine, reduce screen time 1 hour before bed, limit caffeine after 14:00.\n3. Occupational health support and stress management.\n4. Consider SSRI if symptoms persist after 6 weeks of CBT.', 'Return for follow-up assessment in 4 weeks. Contact clinic if suicidal thoughts or severe anxiety develop. Occupational health services can provide workplace adjustments.', FALSE, NULL, 60, 'COMPLETED', '2026-07-20T14:00:00', '2026-07-20T15:00:00', '2026-07-20T14:00:00'),
(4,  1,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),    (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),       'Annual check-up and preventive health review', NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 30, 'IN_PROGRESS', '2026-07-24T09:00:00', NULL, '2026-07-24T09:00:00'),
(5,  5,  (SELECT system_id FROM users WHERE email='elias.dube@carenexus.com'),    (SELECT system_id FROM users WHERE email='rudo.sithole@carenexus.com'),      'Child wellness check and vaccination update', NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 60, 'IN_PROGRESS', '2026-07-24T10:30:00', NULL, '2026-07-24T10:30:00'),
(6,  8,  (SELECT system_id FROM users WHERE email='thomas.dube@carenexus.com'),   (SELECT system_id FROM users WHERE email='amara.osei@carenexus.com'),        'Hypertension and cardiac risk assessment', NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 30, 'DRAFT', NULL, NULL, '2026-07-22T10:00:00'),
(7,  10, (SELECT system_id FROM users WHERE email='agnes.zimba@carenexus.com'),   (SELECT system_id FROM users WHERE email='emeka.eze@carenexus.com'),         'Chronic kidney disease review and medication adjustment', NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 45, 'DRAFT', NULL, NULL, '2026-08-05T09:30:00'),
