(10, 15, (SELECT system_id FROM users WHERE email='florence.zimba@carenexus.com'),(SELECT system_id FROM users WHERE email='amara.osei@carenexus.com'),        'Cancer remission follow-up and lymphedema management', NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 45, 'DRAFT', NULL, NULL, '2026-07-25T13:00:00'),
