INSERT INTO prescriptions (prescription_id, patient_system_id, doctor_system_id, consultation_id, medication_name, generic_name, dosage, frequency, route, quantity, refills_allowed, special_instructions, status, prescribed_date, expiry_date, created_at) VALUES
(1,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),   (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   2,    'Amoxicillin 500mg Capsules',       'Amoxicillin',                         '500mg',                                  'Three times daily (every 8 hours)',            'ORAL',    '21 capsules', 0, 'Complete the full 7-day course even if symptoms improve. Take with or without food. Avoid sharing medication. Contact clinic immediately if rash, hives, or difficulty breathing develop.', 'COMPLETED', '2026-06-28', '2026-07-05', '2026-06-28T11:35:00'),
(2,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),   (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   2,    'Paracetamol 1g Tablets',           'Paracetamol (Acetaminophen)',          '1g (2 × 500mg tablets)',                 'Every 4–6 hours as needed for fever or pain', 'ORAL',    '32 tablets',  0, 'Do not exceed 4g (8 tablets of 500mg) in any 24-hour period. Avoid alcohol. Do not combine with other paracetamol-containing products. Discontinue once fever and throat pain resolve.', 'COMPLETED', '2026-06-28', '2026-07-28', '2026-06-28T11:36:00'),
(3,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),   (SELECT system_id FROM users WHERE email='tafara.mutasa@carenexus.com'),  NULL, 'Tretinoin 0.025% Cream',           'Tretinoin (All-trans retinoic acid)',  '0.025% — pea-sized amount per application', 'Nightly (start 3× per week, increase to nightly over 4 weeks)', 'TOPICAL', '30g tube',    1, 'Apply to clean, completely dry skin at night only. Expect initial dryness, peeling, and mild purging in weeks 1–6 — this is normal. If severe irritation occurs reduce to every other night and contact clinic. Avoid eyes, nostrils, corners of mouth, and open wounds. MUST apply SPF 30+ sunscreen every morning — retinoids increase photosensitivity significantly. Do not use if pregnant or planning pregnancy. Keep refrigerated if possible.', 'ACTIVE', '2026-05-20', '2026-08-20', '2026-05-20T10:40:00'),
(4,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),   (SELECT system_id FROM users WHERE email='tafara.mutasa@carenexus.com'),  NULL, 'Clindamycin Phosphate 1% Gel',     'Clindamycin Phosphate',               '1% — thin layer per application',        'Twice daily (morning and evening)',            'TOPICAL', '30g tube',    1, 'Apply a thin layer to affected areas only (cheeks, jawline, upper back). Avoid contact with eyes, mouth, and mucous membranes. Wash hands before and after applying. Use in combination with tretinoin — apply clindamycin in the morning and tretinoin at night. Discontinue if severe skin irritation or diarrhoea develops (rare systemic absorption).', 'ACTIVE', '2026-05-20', '2026-08-20', '2026-05-20T10:41:00'),
(5,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),   (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   NULL, 'Ferrous Sulphate 200mg Tablets',   'Ferrous Sulphate',                    '200mg (equivalent to 65mg elemental iron)', 'Once daily on an empty stomach',              'ORAL',    '90 tablets',  1, 'Take on an empty stomach 30 minutes before food for best absorption. If GI upset occurs, take with a small amount of food. Vitamin C (orange juice) taken alongside enhances iron absorption. Avoid taking within 2 hours of antacids, dairy, or tea. Stools may turn dark/black — this is normal and not a cause for concern. Repeat iron studies in 3 months to assess response.', 'ACTIVE', '2026-05-15', '2026-08-15', '2026-05-15T09:45:00'),
(6,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),   (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   NULL, 'Loratadine 10mg Tablets',          'Loratadine',                          '10mg',                                   'Once daily',                                  'ORAL',    '30 tablets',  0, 'Take at the same time each day. Non-drowsy antihistamine — safe to drive and operate machinery. Avoid alcohol. Discontinue if no improvement after 14 days and consult your doctor.', 'EXPIRED', '2026-03-10', '2026-04-10', '2026-03-10T10:00:00'),
(7,  (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'),   (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   NULL, 'Vitamin D3 1000 IU Capsules',      'Cholecalciferol (Vitamin D3)',         '1000 IU',                                'Once daily with a meal containing fat',       'ORAL',    '90 capsules', 2, 'Take with the largest meal of the day for optimal absorption (fat-soluble vitamin). Maintain adequate calcium intake through diet. Routine 25-OH Vitamin D level to be rechecked at next annual health review. Store in a cool, dry place away from direct sunlight.', 'ACTIVE', '2026-01-08', '2026-12-31', '2026-01-08T09:00:00'),
(8,  (SELECT system_id FROM users WHERE email='elias.dube@carenexus.com'),   (SELECT system_id FROM users WHERE email='nokuthula.mthembu@carenexus.com'), NULL, 'Folic Acid 5mg Tablets',          'Folic Acid (Folate)',                 '5mg',                                    'Once daily',                                  'ORAL',    '90 tablets',  2, 'Take at the same time each day. Particularly important if planning another pregnancy — folic acid reduces risk of neural tube defects. Continue for at least 3 months preconceptionally and through first trimester if pregnant. May be taken with or without food.', 'ACTIVE', '2026-06-10', '2026-12-10', '2026-06-10T09:50:00'),
(9,  (SELECT system_id FROM users WHERE email='elias.dube@carenexus.com'),   (SELECT system_id FROM users WHERE email='emeka.eze@carenexus.com'),     NULL, 'Metformin 500mg Tablets',          'Metformin Hydrochloride',             '500mg',                                  'Twice daily with meals',                      'ORAL',    '60 tablets',  3, 'Take with or immediately after food to reduce GI side effects (nausea, diarrhoea). Swallow whole — do not crush. Do not take if feeling unwell, dehydrated, or before major surgery/contrast dye procedures. Monitor blood glucose as advised. HbA1c review in 3 months. Avoid excessive alcohol.', 'ACTIVE', '2026-07-08', '2027-01-08', '2026-07-08T09:30:00'),
(10, (SELECT system_id FROM users WHERE email='thomas.dube@carenexus.com'),  (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   NULL, 'Amlodipine 5mg Tablets',           'Amlodipine',                          '5mg',                                    'Once daily (morning)',                        'ORAL',    '30 tablets',  5, 'Take at the same time each day. Do not stop suddenly without consulting your doctor. Monitor for ankle swelling or dizziness. Avoid grapefruit juice.', 'ACTIVE', '2026-06-15', '2026-12-15', '2026-06-15T10:00:00'),
(11, (SELECT system_id FROM users WHERE email='thomas.dube@carenexus.com'),  (SELECT system_id FROM users WHERE email='emeka.eze@carenexus.com'),     NULL, 'Metformin 500mg Tablets',          'Metformin Hydrochloride',             '500mg',                                  'Twice daily (with breakfast and dinner)',     'ORAL',    '60 tablets',  5, 'Take with food to reduce GI side effects. Monitor blood glucose regularly. Avoid alcohol. Withhold before contrast dye procedures. HbA1c review every 3 months.', 'ACTIVE', '2026-06-15', '2026-12-15', '2026-06-15T10:05:00'),
(12, (SELECT system_id FROM users WHERE email='thomas.dube@carenexus.com'),  (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   NULL, 'Atorvastatin 10mg Tablets',        'Atorvastatin',                        '10mg',                                   'Once daily (at night)',                       'ORAL',    '30 tablets',  5, 'Take at bedtime. Report any unexplained muscle pain, tenderness, or weakness immediately. Avoid excessive alcohol. Lipid panel review in 3 months.', 'ACTIVE', '2026-06-15', '2026-12-15', '2026-06-15T10:10:00'),
(13, (SELECT system_id FROM users WHERE email='agnes.zimba@carenexus.com'),  (SELECT system_id FROM users WHERE email='emeka.eze@carenexus.com'),     NULL, 'Calcium Carbonate 500mg Tablets',  'Calcium Carbonate',                   '500mg',                                  'Twice daily (with meals)',                    'ORAL',    '60 tablets',  3, 'Take with meals to improve absorption. Do not take within 2 hours of other medications. Monitor serum calcium levels. Essential for bone health management in CKD.', 'ACTIVE', '2026-07-01', '2027-01-01', '2026-07-01T09:00:00'),
(14, (SELECT system_id FROM users WHERE email='agnes.zimba@carenexus.com'),  (SELECT system_id FROM users WHERE email='emeka.eze@carenexus.com'),     NULL, 'Furosemide 40mg Tablets',          'Furosemide',                          '40mg',                                   'Once daily (morning)',                        'ORAL',    '30 tablets',  2, 'Take in the morning to avoid nocturia. Monitor weight daily — report gain of >1kg in a day. Monitor potassium levels regularly. Stay well hydrated but within fluid restriction limits. Avoid NSAIDs.', 'ACTIVE', '2026-07-01', '2026-10-01', '2026-07-01T09:05:00'),
(15, (SELECT system_id FROM users WHERE email='agnes.zimba@carenexus.com'),  (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'),   NULL, 'Tramadol 50mg Capsules',           'Tramadol Hydrochloride',              '50mg',                                   'Every 6 hours as needed for pain',            'ORAL',    '20 capsules', 1, 'Use lowest effective dose for shortest duration. Do not exceed 4 doses in 24 hours. May cause drowsiness — do not drive. Do not take with alcohol. Use cautiously given CKD — monitor renal function. NSAIDs are contraindicated.', 'ACTIVE', '2026-07-20', '2026-08-20', '2026-07-20T10:00:00')
