INSERT INTO medical_records (record_id, patient_system_id, doctor_system_id, consultation_id, record_type, title, description, treatment_plan, observations, icd_codes, is_deleted, deleted_at, created_at, updated_at) VALUES
(1, (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'), (SELECT system_id FROM users WHERE email='amara.osei@carenexus.com'),  1, 'CONSULT', 'Cardiology Consultation — Chest Pain & Palpitations',  'Patient presented via video consultation with a 2-week history of intermittent chest tightness and palpitations, worse on exertion and associated with psychosocial stress. HR 78 bpm regular, BP 122/78 mmHg, SpO2 99%. 12-lead ECG reviewed — normal sinus rhythm, no ST changes.', 'Lifestyle modification: reduce caffeine, improve sleep hygiene, moderate exercise. Stress management referral. No pharmacological intervention. Cardiology review in 3 months if symptoms persist.', 'ECG normal. Symptoms strongly linked to stress and caffeine intake. Low pre-test probability for structural cardiac pathology. No murmurs on auscultation.', '[{"code": "R00.2", "description": "Palpitations"}, {"code": "R07.9", "description": "Chest pain, unspecified"}]'::jsonb, FALSE, NULL, '2026-07-10T14:45:00', '2026-07-10T14:45:00'),
(2, (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'), (SELECT system_id FROM users WHERE email='amara.osei@carenexus.com'),  1, 'LAB',     '12-Lead ECG Report — Cardiology Review',               '12-lead electrocardiogram performed and reviewed during video consultation on 10 Jul 2026. Rhythm: Normal sinus rhythm. Rate: 78 bpm. PR interval: 160 ms. QRS duration: 88 ms. QTc: 410 ms. ST segments: No elevation or depression. T-waves: Normal morphology in all leads. No ectopic beats captured during recording.', NULL, 'ECG within normal limits. No evidence of ischaemia, arrhythmia, or conduction abnormality at the time of recording. Previous ECG (GP, April 2026) also normal. Holter monitoring recommended only if symptoms worsen or become more frequent.', '[{"code": "R00.2", "description": "Palpitations"}, {"code": "Z03.89", "description": "Encounter for observation for other suspected diseases and conditions ruled out"}]'::jsonb, FALSE, NULL, '2026-07-10T15:00:00', '2026-07-10T15:00:00'),
(3, (SELECT system_id FROM users WHERE email='linda.moyo@carenexus.com'), (SELECT system_id FROM users WHERE email='james.banda@carenexus.com'), 2, 'CONSULT', 'GP Consultation — Bacterial Pharyngitis',              'Patient presented with 5-day history of worsening sore throat, dry cough, and malaise with low-grade fever peaking at 38.1°C. Centor score 4/4. Oropharynx erythematous with bilateral tonsillar enlargement (+2) and right-sided white exudate. Tender cervical lymphadenopathy bilaterally.', 'Amoxicillin 500mg TDS for 7 days. Paracetamol 1g QDS PRN. Warm saline gargles 4x daily. Adequate fluids and rest. Avoid sharing utensils.', 'High Centor score. Clinical signs consistent with acute bacterial pharyngitis (likely Group A Streptococcus). Treating empirically.', '[{"code": "J02.9", "description": "Acute pharyngitis, unspecified"}, {"code": "R05.9", "description": "Fever, unspecified"}]'::jsonb, FALSE, NULL, '2026-06-28T11:30:00', '2026-06-28T11:30:00')
